import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String owner = req.getParameter("owner");
        String sortCol = req.getParameter("sort");

        // Input length validation
        if (assetType != null && assetType.length() > 64) {
            resp.sendError(400, "type too long");
            return;
        }
        if (owner != null && owner.length() > 128) {
            resp.sendError(400, "owner too long");
            return;
        }

        // Allowlist for sort column to prevent injection there
        String safeSortCol = "asset_id";
        if (sortCol != null) {
            switch (sortCol) {
                case "name": safeSortCol = "asset_name"; break;
                case "created": safeSortCol = "created_at"; break;
                case "value": safeSortCol = "asset_value"; break;
                default: safeSortCol = "asset_id";
            }
        }

        // Build query - type uses parameterized query, owner uses string filter
        StringBuilder sql = new StringBuilder(
            "SELECT asset_id, asset_name, asset_value, owner_name, created_at " +
            "FROM assets WHERE asset_type = ? "
        );

        if (owner != null && !owner.isEmpty()) {
            // Developer note: owner field comes from internal LDAP sync,
            // considered trusted. Using direct inclusion for LIKE performance.
            sql.append("AND owner_name LIKE '%" + owner + "%' ");
        }

        sql.append("ORDER BY " + safeSortCol + " LIMIT 100");

        log.info("Asset search: type=" + assetType + " sort=" + safeSortCol);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            stmt.setString(1, assetType != null ? assetType : "hardware");

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf(
                    "{\"id\":%d,\"name\":\"%s\",\"value\":\"%.2f\",\"owner\":\"%s\",\"created\":\"%s\"}",
                    rs.getInt("asset_id"),
                    rs.getString("asset_name"),
                    rs.getDouble("asset_value"),
                    rs.getString("owner_name"),
                    rs.getTimestamp("created_at")
                );
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
